  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'bd32357e-c161-4052-abdf-a267b5139644', 'aedc9bf9-5810-404d-af31-095336b601fc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Why might some children in Haryana have less access to schooling compared to Kerala?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Haryana has better educational facilities."},{"id":"b","text":"Parents may not afford the cost of education due to lower income."},{"id":"c","text":"Higher literacy rates indicate better school resources."},{"id":"d","text":"Kerala invests more in public schools."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-173Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'bd32357e-c161-4052-abdf-a267b5139644', 'aedc9bf9-5810-404d-af31-095336b601fc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$How does the data on per capita income reflect Haryana’s position compared to Kerala?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Haryana has a higher average income but similar literacy rates."},{"id":"b","text":"Haryana and Kerala have comparable income levels but different health statuses."},{"id":"c","text":"Haryana has higher income but lower education ratios."},{"id":"d","text":"Kerala has better per capita income with poorer health care facilities."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-173Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'bd32357e-c161-4052-abdf-a267b5139644', 'aedc9bf9-5810-404d-af31-095336b601fc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Which statement accurately reflects the concept of collective provision versus individual provision?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Collective provision is always cheaper than individual provision."},{"id":"b","text":"Individual provision is less effective in providing security than collective provision."},{"id":"c","text":"Both methods are equally efficient and cost-effective."},{"id":"d","text":"Effective collective provision can reduce costs compared to individual efforts."}]$qbx$::jsonb, $qbx$d$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-173Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
