  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'bd32357e-c161-4052-abdf-a267b5139644', 'aedc9bf9-5810-404d-af31-095336b601fc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$How does the availability of essential healthcare relate to per capita income in Haryana?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"It is directly proportional, meaning higher income means better healthcare access."},{"id":"b","text":"Per capita income has no relation to healthcare availability."},{"id":"c","text":"Healthcare facilities are funded by community contributions regardless of income level."},{"id":"d","text":"Inadequate per capita income indicates poor health status, but not vice versa."}]$qbx$::jsonb, $qbx$d$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-173Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
